mapper.select:

and m.id = #{id}
and m.season_id = #{seasonId}
and m.division_id = #{divisionId}
and m.stage_id = #{stageId}
and m.series_id = #{seriesId}
and m.schedule_batch_id = #{scheduleBatchId}
and m.round_no = #{roundNo}
and m.match_status = #{matchStatus}
and m.publish_status = #{publishStatus}

    and (m.home_event_team_id = #{eventTeamId} or m.away_event_team_id = #{eventTeamId})


    and (ht.team_name_snapshot like concat('%', #{teamName}, '%') or at.team_name_snapshot like concat('%', #{teamName}, '%'))

order by m.round_no asc, m.match_time asc, m.id asc

select  from basket_match
where stage_id = #{stageId}
  and round_no = #{roundNo}
  and 
order by bracket_slot asc, match_time asc, id asc
